css:
.tier .en{font-size:clamp(28px,4vw,56px); font-weight:300; letter-spacing:.2em; color:#8a8a90; line-height:1}
.tier .ja{font-size:11px; font-weight:700; letter-spacing:.12em; color:#5b52a3; margin-top:6px}
/* 和文主・欧文従は1要素で完結させる */
.nav a{display:grid; justify-items:center; line-height:1.2}
.nav a::after{content:attr(data-en); font-size:9px; letter-spacing:.18em; color:#3f9a5a; text-transform:lowercase; margin-top:6px}
/* 極小欧文の積み組み */
.eyebrow{position:absolute; right:0; top:4px; width:5em; font-size:7px; line-height:1.7; text-align:center; font-weight:700; letter-spacing:.06em}
